#include <iostream>
#include <string>

int main() {
    std::string input;
    std::getline(std::cin, input);
    int answer = 0;
    int count = 1;
    char previous = '#';

    for (size_t i = 0; i < input.length(); ++i) {
        char current = input[i];
        if (current == previous) {
            ++count;
        } else {
            if (count % 2 == 0) {
                ++answer;
            }
            count = 1;
        }
        previous = current;
    }
    if (count % 2 == 0) {
        ++answer;
    }
    std::cout << answer << std::endl;
    return 0;
}
